# --- rolling_three_month_sum: original lines 3421-3462
def rolling_three_month_sum(
    values
):
    values = np.asarray(
        values,
        dtype=np.float64
    )

    out = np.full_like(
        values,
        np.nan
    )

    complete = (
        np.isfinite(
            values[:, :-2]
        )
        &
        np.isfinite(
            values[:, 1:-1]
        )
        &
        np.isfinite(
            values[:, 2:]
        )
    )

    total = (
        values[:, :-2]
        +
        values[:, 1:-1]
        +
        values[:, 2:]
    )

    out[:, 2:] = np.where(
        complete,
        total,
        np.nan
    )

    return out


# --- normal_from_probability: original lines 3465-3482
def normal_from_probability(
    p
):
    p = np.clip(
        p,
        NORMAL_PROB_EPS,
        1.0 -
        NORMAL_PROB_EPS
    )

    return (
        np.sqrt(2.0)
        *
        special.erfinv(
            2.0 * p -
            1.0
        )
    )


