# --- truthy: original lines 4874-4895
def truthy(
    x
):
    if pd.isna(x):
        return False

    if isinstance(
        x,
        str
    ):
        return (
            x.strip()
            .lower()
            in {
                '1',
                'true',
                'yes',
                'y'
            }
        )

    return bool(x)


# --- int_or_none: original lines 4898-4912
def int_or_none(
    x
):
    if pd.isna(x):
        return None

    try:
        return int(
            round(
                float(x)
            )
        )

    except Exception:
        return None


# --- exact_date: original lines 4915-4958
def exact_date(
    year,
    month,
    day
):

    year = int(year)
    month = int(month)
    day = int(day)

    if not (
        1 <= month <= 12
    ):
        return None

    last = (
        pycalendar.monthrange(
            year,
            month
        )[1]
    )

    # Project rule.
    if (
        month == 2
        and
        day == 29
        and
        last == 28
    ):
        day = 28

    elif (
        day < 1
        or
        day > last
    ):
        return None

    return pd.Timestamp(
        year=year,
        month=month,
        day=day
    )


# --- aggregate_gs: original lines 5369-5661
def aggregate_gs(
    monthly,
    monthly_reason,
    metric_name
):

    n = len(
        season_plan
    )

    value = np.full(
        n,
        np.nan
    )

    coverage = np.full(
        n,
        np.nan
    )

    support_days = np.zeros(
        n
    )

    n_months = np.zeros(
        n,
        dtype=np.int16
    )

    input_missing_months = np.zeros(
        n,
        dtype=np.int16
    )

    fit_invalid_months = np.zeros(
        n,
        dtype=np.int16
    )

    outside_support_months = np.zeros(
        n,
        dtype=np.int16
    )

    status = np.empty(
        n,
        dtype=object
    )

    missing_reason = np.empty(
        n,
        dtype=object
    )


    for i, row in (
        season_plan.iterrows()
    ):

        if (
            int(
                row[
                    'gs_calendar_valid'
                ]
            )
            != 1
        ):
            status[i] = (
                'INVALID_CALENDAR'
            )

            missing_reason[i] = (
                'INVALID_CALENDAR'
            )

            continue


        pos = row[
            '_month_positions'
        ]

        weights = np.asarray(
            row[
                '_overlap_days'
            ],
            dtype=float
        )

        duration = float(
            row[
                'gs_duration_recalculated_days'
            ]
        )

        admin_pos = int(
            row[
                '_admin_position'
            ]
        )


        source_values = monthly[
            admin_pos,
            pos
        ]

        reasons = monthly_reason[
            admin_pos,
            pos
        ]


        valid = np.isfinite(
            source_values
        )


        n_months[i] = int(
            valid.sum()
        )


        input_missing_months[i] = int(
            (
                reasons
                ==
                REASON_INPUT_MISSING
            ).sum()
        )


        fit_invalid_months[i] = int(
            (
                reasons
                ==
                REASON_FIT_INVALID
            ).sum()
        )


        outside_support_months[i] = int(
            (
                reasons
                ==
                REASON_OUTSIDE_SUPPORT
            ).sum()
        )


        supported = float(
            np.where(
                valid,
                weights,
                0
            ).sum()
        )


        support_days[i] = (
            supported
        )


        coverage[i] = np.clip(
            supported /
            duration,
            0,
            1
        )


        if (
            supported <= 0
        ):
            status[i] = (
                'MISSING_DATA'
            )

            missing_reason[i] = (
                'NO_VALID_INDEX_MONTH'
            )

            continue


        # -------------------------------------------------------------
        # Require valid monthly-index support across the full season.
        # -------------------------------------------------------------

        full = (
            coverage[i]
            >=
            FULL_COVERAGE_TOLERANCE
        )


        if not full:

            status[i] = (
                'MISSING_DATA'
            )

            if (
                input_missing_months[i]
                > 0
            ):
                missing_reason[i] = (
                    'INPUT_MONTH_MISSING'
                )

            elif (
                fit_invalid_months[i]
                > 0
            ):
                missing_reason[i] = (
                    'BASELINE_FIT_INVALID'
                )

            elif (
                outside_support_months[i]
                > 0
            ):
                missing_reason[i] = (
                    'SPEI_OUTSIDE_'
                    'FITTED_SUPPORT'
                )

            else:
                missing_reason[i] = (
                    'PARTIAL_MONTHLY_'
                    'INDEX_SUPPORT'
                )

            continue


        value[i] = (
            np.sum(
                source_values *
                weights
            )
            /
            supported
        )


        status[i] = (
            'COMPLETE'
        )

        missing_reason[i] = (
            'NONE'
        )


    return pd.DataFrame({

        metric_name:
            value,

        metric_name +
        '_season_coverage_fraction':
            coverage,

        metric_name +
        '_supported_overlap_days':
            support_days,

        metric_name +
        '_contributing_months':
            n_months,

        metric_name +
        '_input_missing_months':
            input_missing_months,

        metric_name +
        '_fit_invalid_months':
            fit_invalid_months,

        metric_name +
        '_outside_support_months':
            outside_support_months,

        metric_name +
        '_status':
            status,

        metric_name +
        '_missing_reason':
            missing_reason
    })


# --- add_ensemble: original lines 5750-5863
def add_ensemble(
    frame,
    family
):

    source_cols = [
        f'{family}_gs_'
        f'{s}'
        for s
        in SOURCES
    ]

    m = (
        frame[
            source_cols
        ]
        .to_numpy(
            dtype=float
        )
    )

    valid = np.isfinite(
        m
    )

    n = valid.sum(
        axis=1
    )

    total = np.where(
        valid,
        m,
        0
    ).sum(
        axis=1
    )

    mean = np.divide(
        total,
        n,
        out=np.full(
            len(frame),
            np.nan
        ),
        where=n > 0
    )


    sq = np.where(
        valid,
        (
            m -
            mean[:, None]
        ) ** 2,
        0
    ).sum(
        axis=1
    )


    # Report population SD when at least two sources are available.
    sd = np.full(
        len(frame),
        np.nan
    )

    two_plus = (
        n >= 2
    )

    sd[
        two_plus
    ] = np.sqrt(
        sq[
            two_plus
        ]
        /
        n[
            two_plus
        ]
    )


    frame[
        f'{family}_gs_ensmean'
    ] = mean

    frame[
        f'{family}_gs_n_sources'
    ] = n.astype(
        np.int8
    )

    frame[
        f'{family}_gs_ens_sd'
    ] = sd

    frame[
        f'{family}_gs_status'
    ] = np.select(
        [
            n == 3,
            n == 2,
            n == 1,
            n == 0
        ],
        [
            'THREE_SOURCES',
            'TWO_SOURCES',
            'ONE_SOURCE',
            'MISSING_ALL_SOURCES'
        ],
        default='UNKNOWN'
    )
